mapper.select:
SELECT  FROM appointments 
  BINARY status=BINARY #{status}AND INSTR(BINARY host_name_snapshot,BINARY #{host})>0AND INSTR(BINARY visitor_name_snapshot,BINARY #{visitor})>0AND BINARY host_id=BINARY #{hostId}
  AND ((visitor_id IS NOT NULL AND visitor_id != '' AND BINARY visitor_id=BINARY #{visitorId}) OR ((visitor_id IS NULL OR visitor_id='') AND (BINARY visitor_phone_snapshot=BINARY #{scopePhone}FALSE OR BINARY visitor_name_snapshot=BINARY #{scopeName}FALSE)))AND BINARY visitor_phone_snapshot=BINARY #{visitorPhone}
  ORDER BY created_at DESC,id
